import random
from itertools import combinations

def check_girth(n, edges, min_girth=7):
    """Check if graph has girth >= min_girth using BFS from each vertex."""
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for start in range(n):
        dist = {start: 0}
        parent = {start: None}
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def is_k_colorable(n, edges, k=4):
    """Check if graph is k-colorable using backtracking with MRV heuristic."""
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * n

    def get_valid_colors(v):
        used = {color[u] for u in adj[v] if color[u] != -1}
        return [c for c in range(k) if c not in used]

    def backtrack():
        # Find uncolored vertex with minimum remaining values
        uncolored = [v for v in range(n) if color[v] == -1]
        if not uncolored:
            return True

        v = min(uncolored, key=lambda x: len(get_valid_colors(x)))
        valid = get_valid_colors(v)

        for c in valid:
            color[v] = c
            if backtrack():
                return True
            color[v] = -1
        return False

    return backtrack()

def find_graph(n=22, min_edges=17, max_edges=25, trials=50000):
    """Search for a graph with required properties."""
    all_pairs = list(combinations(range(n), 2))

    for num_edges in range(min_edges, max_edges + 1):
        print(f"Trying {num_edges} edges...")
        for trial in range(trials // (max_edges - min_edges + 1)):
            edges = random.sample(all_pairs, num_edges)

            # Quick check: max degree should be reasonable for 4-colorability
            deg = [0] * n
            for u, v in edges:
                deg[u] += 1
                deg[v] += 1
            if max(deg) > 10:  # Skip if max degree too high
                continue

            if check_girth(n, edges, 7):
                if is_k_colorable(n, edges, 4):
                    return edges
    return None

random.seed(42)
result = find_graph()
if result:
    print(f"Found graph with {len(result)} edges:")
    print(result)
else:
    print("No graph found")

